from lib import R
F = "34-mains-airfryer-tacos-more.txt"
def M(t, cu, prep, cook, serv, ings, steps, meals="Dinner, Main dish"):
    R(F, t, "Main", cu, prep, cook, serv, meals, ings, steps)

# ---------------- air fryer ----------------
M("Air Fryer Paprika Chicken Thighs", "American", 5, 22, 4, "8|chicken thighs, boneless; 2 tsp|smoked paprika; 1 tsp|garlic powder; 1 tsp|brown sugar; 1 tbsp|olive oil; |salt; |black pepper",
  "Mix the paprika, garlic powder, sugar, 1 tsp salt and some pepper / Rub the chicken with the oil, then the spice mix / Air fry at 190°C (375°F) for 18 to 22 minutes, turning halfway, until the juices run clear (75°C/165°F inside) / Rest 5 minutes before serving")
M("Air Fryer Coconut Shrimp", "Caribbean", 15, 10, 4, "400 g|shrimp, peeled, tails on; 40 g|flour; 2|eggs; 60 g|shredded coconut; 40 g|panko; |salt; |cooking spray; 4 tbsp|sweet chili sauce",
  "Set out three bowls: flour seasoned with salt, beaten eggs, and the coconut mixed with the panko / Dip each shrimp in flour, egg, then the coconut mix, pressing it on / Spray the basket and the shrimp, then air fry at 200°C (400°F) for 8 to 10 minutes, turning once, until golden / Serve with sweet chili sauce for dipping")
M("Air Fryer Crispy Fish Fingers", "British", 15, 10, 4, "500 g|white fish fillets, cut into fingers; 40 g|flour; 2|eggs; 80 g|panko; 0.5 tsp|paprika; 1|lemon; |salt; |cooking spray",
  "Pat the fish dry and season with salt / Coat each finger in flour, then beaten egg, then panko mixed with the paprika / Spray with oil and air fry at 200°C (400°F) for 8 to 10 minutes, turning halfway, until crisp and the fish flakes / Serve with lemon wedges, peas and tartar sauce or ketchup")
M("Air Fryer BBQ Drumsticks", "American", 5, 25, 4, "8|chicken drumsticks; 1 tbsp|brown sugar; 2 tsp|smoked paprika; 1 tsp|garlic powder; 1 tsp|onion powder; 1 tbsp|vegetable oil; 4 tbsp|bbq sauce; |salt",
  "Mix the sugar, paprika, garlic and onion powders and 1 tsp salt / Toss the drumsticks in the oil and the rub / Air fry at 190°C (375°F) for 22 to 25 minutes, turning twice, until cooked through / Brush with BBQ sauce and air fry 2 to 3 minutes more until sticky")
M("Air Fryer Stuffed Peppers", "American", 15, 18, 4, "4|bell peppers, tops cut off and seeded; 250 g|cooked rice; 300 g|ground beef, browned; 200 g|canned tomatoes; 1 tsp|italian seasoning; 80 g|mozzarella, grated; |salt; |black pepper",
  "Mix the rice, browned beef, tomatoes and Italian seasoning and season well / Pack the filling into the peppers / Air fry at 180°C (350°F) for 15 minutes, top with the cheese and cook 3 minutes more until melted and the peppers are tender")
M("Air Fryer Mini Turkey Meatloaves", "American", 15, 18, 4, "500 g|ground turkey; 1|egg; 40 g|breadcrumbs; 1|onion, grated; 1 tsp|dried thyme; 1 tbsp|worcestershire sauce; 4 tbsp|ketchup; 1 tbsp|brown sugar; |salt; |black pepper",
  "Mix the turkey, egg, breadcrumbs, onion, thyme, Worcestershire sauce, 1 tsp salt and pepper / Shape into 4 small loaves / Air fry at 180°C (350°F) for 12 minutes / Mix the ketchup and sugar, brush over the loaves and cook 5 to 6 minutes more until glazed and cooked through")
M("Air Fryer Garlic Butter Steak Bites", "American", 5, 9, 2, "500 g|sirloin steak, in 3 cm cubes; 1 tbsp|vegetable oil; 1 tsp|garlic powder; 2 tbsp|butter, melted; 2 cloves|garlic, minced; 1 tbsp|parsley, chopped; |salt; |black pepper",
  "Toss the steak with the oil, garlic powder, salt and pepper / Air fry at 200°C (400°F) for 7 to 9 minutes, shaking halfway, for medium / Toss with the butter, fresh garlic and parsley and serve")
M("Air Fryer Chicken Parmesan", "Italian-American", 15, 16, 4, "2|chicken breasts, halved horizontally; 40 g|flour; 1|egg; 60 g|panko; 30 g|parmesan, grated; 200 ml|marinara sauce; 100 g|mozzarella, grated; |cooking spray; |salt",
  "Season the chicken. Coat in flour, beaten egg, then panko mixed with parmesan / Spray and air fry at 200°C (400°F) for 10 minutes, turning once / Spoon marinara over each piece, top with mozzarella and cook 4 to 6 minutes more until bubbling / Serve with spaghetti or salad")
M("Air Fryer Sausages with Onions and Peppers", "American", 5, 16, 4, "8|sausages; 2|bell peppers, sliced; 1|onion, sliced; 1 tbsp|olive oil; 1 tsp|italian seasoning; 4|hot dog buns",
  "Toss the peppers and onion with the oil and seasoning / Air fry the sausages at 190°C (375°F) for 6 minutes, add the vegetables and cook 10 minutes more, shaking twice / Serve the sausages in buns piled with the peppers and onions")
M("Air Fryer Pork Schnitzel", "German", 15, 12, 4, "4|pork chops, boneless, pounded thin; 40 g|flour; 2|eggs; 80 g|breadcrumbs; 1|lemon; |cooking spray; |salt; |black pepper",
  "Season the pork. Dip in flour, then beaten egg, then breadcrumbs / Spray well and air fry at 200°C (400°F) for 10 to 12 minutes, turning halfway, until golden and cooked through / Serve with lemon wedges, potato salad or a green salad")
M("Air Fryer Crispy Tofu Rice Bowls", "Asian", 10, 15, 2, "400 g|firm tofu, pressed and cubed; 1 tbsp|cornstarch; 1 tbsp|tamari; 1 tsp|sesame oil; 250 g|cooked rice; 1|cucumber, sliced; 1|carrot, grated; 2 tbsp|sweet chili sauce",
  "Toss the tofu with the tamari and sesame oil, then the cornstarch / Air fry at 200°C (400°F) for 13 to 15 minutes, shaking twice, until crisp / Divide the rice between bowls, add the tofu, cucumber and carrot, and drizzle with sweet chili sauce")
M("Air Fryer Lemon Pepper Salmon Bites", "American", 5, 8, 3, "500 g|salmon fillet, skinned, in cubes; 1 tbsp|olive oil; 1|lemon, zested; 1 tsp|black pepper; 0.5 tsp|garlic powder; |salt",
  "Toss the salmon with the oil, lemon zest, pepper, garlic powder and salt / Air fry at 200°C (400°F) for 6 to 8 minutes, shaking once, until just cooked / Squeeze over the lemon and serve over rice or salad")

# ---------------- tacos ----------------
TC = [
 ("Chicken Tinga Tacos", "Mexican", 10, 25, "500 g|chicken breast; 1|onion, sliced; 2 cloves|garlic; 1 can|canned tomatoes; 2|chipotle peppers in adobo", "Poach the chicken in salted water for 15 minutes, then shred / Soften the onion and garlic in 1 tbsp oil, blend the tomatoes with the chipotles and add, then simmer 5 minutes / Stir in the chicken and simmer 5 minutes more", "1|avocado, sliced; 4 tbsp|sour cream; 50 g|queso fresco, crumbled"),
 ("Al Pastor-Style Pork Tacos", "Mexican", 20, 15, "600 g|pork shoulder, thinly sliced; 2 tbsp|achiote paste; 3 tbsp|pineapple juice; 1 tsp|cumin; 200 g|pineapple, diced", "Mix the achiote paste, pineapple juice and cumin, coat the pork and marinate at least 20 minutes / Sear the pork in batches in a very hot pan with 1 tbsp oil until charred at the edges, then chop / Sear the pineapple until caramelised", "1|onion, finely chopped; 1 handful|cilantro; 2|limes"),
 ("Crispy Black Bean Tacos", "Mexican", 10, 15, "2 can|black beans, drained; 1 tsp|cumin; 1 tsp|chili powder; 100 g|cheddar, grated", "Mash the beans roughly with the cumin, chili powder and salt / Spread beans and cheese on half of each tortilla and fold / Fry in a lightly oiled pan for 2 to 3 minutes a side until crisp", "1 handful|lettuce, shredded; 4 tbsp|salsa; 1|lime"),
 ("Mushroom and Poblano Tacos", "Mexican", 10, 15, "400 g|mushrooms, sliced; 2|poblano peppers, sliced; 1|onion, sliced; 1 tsp|cumin; 1 tsp|dried oregano", "Char the poblanos and onion in 1 tbsp oil in a hot pan for 5 minutes / Add the mushrooms and cook 8 minutes until browned, then season with cumin, oregano and salt", "1|avocado, sliced; 50 g|queso fresco, crumbled; 1|lime"),
 ("Ground Turkey Tacos", "Tex-Mex", 5, 15, "500 g|ground turkey; 1|onion, chopped; 2 tbsp|taco seasoning; 100 ml|tomato sauce", "Brown the turkey and onion in 1 tbsp oil for 8 minutes / Stir in the taco seasoning and tomato sauce and simmer 4 minutes", "1 handful|lettuce, shredded; 100 g|cheddar, grated; 1|tomato, diced"),
 ("Carne Asada Tacos", "Mexican", 15, 10, "600 g|flank steak; 2|limes; 3 cloves|garlic, minced; 1 tsp|cumin; 1 handful|cilantro, chopped", "Marinate the steak with the juice of 1 lime, garlic, cumin, half the cilantro, 2 tbsp oil and salt for at least 30 minutes / Grill or sear in a very hot pan 4 to 5 minutes a side, rest 5 minutes and slice thinly across the grain", "1|onion, finely chopped; 4 tbsp|salsa verde; 1|avocado"),
 ("Lentil Walnut Tacos", "Tex-Mex", 10, 20, "200 g|brown lentils; 60 g|walnuts, finely chopped; 2 tbsp|taco seasoning; 1|onion, chopped", "Simmer the lentils in water for 20 minutes until tender, then drain / Fry the onion in 1 tbsp oil for 5 minutes, add the walnuts for 2 minutes, then the lentils, taco seasoning and a splash of water, and cook until thick", "1 handful|lettuce, shredded; 1|avocado, sliced; 4 tbsp|salsa"),
 ("Korean BBQ Beef Tacos", "Korean", 15, 8, "500 g|steak, thinly sliced; 3 tbsp|soy sauce; 1 tbsp|brown sugar; 1 tbsp|sesame oil; 1 tbsp|gochujang", "Mix the soy sauce, sugar, sesame oil and gochujang and toss with the beef for 15 minutes / Sear in a very hot pan in batches for 2 minutes until caramelised", "150 g|kimchi, chopped; 2|green onions, sliced; 1 tbsp|sesame seeds"),
 ("Chipotle Salmon Tacos", "Tex-Mex", 10, 10, "500 g|salmon fillet; 1|chipotle pepper in adobo, minced; 1 tbsp|honey; 1|lime", "Mix the chipotle, honey, lime juice and salt and brush over the salmon / Roast at 200°C (400°F) for 10 to 12 minutes, then flake", "150 g|red cabbage, shredded; 4 tbsp|sour cream; 1 handful|cilantro"),
 ("Chorizo and Potato Tacos", "Mexican", 10, 20, "200 g|chorizo, diced; 400 g|potatoes, in small dice; 1|onion, chopped", "Boil the potatoes for 5 minutes and drain / Fry the chorizo for 3 minutes, add the onion and potatoes and cook 12 minutes until the potatoes are crisp", "4 tbsp|salsa verde; 50 g|queso fresco, crumbled; 1 handful|cilantro"),
]
for t, cu, prep, cook, filling, steps, tops in TC:
    tort = "8|corn tortillas" if "Crispy Black" not in t else "8|flour tortillas"
    st = steps.split(" / ")
    if "Crispy Black" not in t:
        st.append("Warm the tortillas in a dry pan or wrapped in foil in the oven")
        st.append("Fill the tortillas and finish with the toppings")
    else:
        st.append("Open each taco slightly and tuck in the toppings")
    M(t, cu, prep, cook, 4, filling + "; " + tort + "; " + tops + "; 1 tbsp|vegetable oil; |salt", st)

# ---------------- fried rice and noodles ----------------
M("Nasi Goreng", "Indonesian", 10, 12, 4, "600 g|cooked rice, cold; 2 tbsp|vegetable oil; 3|shallots, sliced; 3 cloves|garlic, chopped; 1|red chili, chopped; 200 g|chicken breast, diced; 3 tbsp|kecap manis; 1 tbsp|soy sauce; 4|eggs; 1|cucumber, sliced",
  "Fry the shallots, garlic and chili in the oil for 2 minutes / Add the chicken and stir-fry 4 minutes until cooked / Add the rice, kecap manis and soy sauce and stir-fry over high heat 4 minutes until hot and lightly caramelised / Fry the eggs separately and serve one on each plate with cucumber slices", "Dinner, Lunch, Main dish")
M("Thai Basil Fried Rice", "Thai", 10, 10, 2, "400 g|cooked rice, cold; 2 tbsp|vegetable oil; 3 cloves|garlic, chopped; 2|thai chilies, sliced; 200 g|ground pork; 1 tbsp|fish sauce; 1 tbsp|oyster sauce; 1 tsp|sugar; 1 large handful|thai basil",
  "Fry the garlic and chilies in the oil for 30 seconds / Add the pork and cook, breaking it up, for 4 minutes / Add the rice, fish sauce, oyster sauce and sugar and stir-fry 3 minutes / Toss in the basil until just wilted and serve", "Dinner, Lunch, Main dish")
M("Bacon and Cabbage Fried Rice", "Asian", 10, 12, 3, "500 g|cooked rice, cold; 4 slices|bacon, chopped; 250 g|cabbage, shredded; 3|green onions, sliced; 2|eggs; 2 tbsp|soy sauce; 1 tsp|sesame oil",
  "Cook the bacon in a large pan until crisp / Add the cabbage and stir-fry 3 minutes / Push to one side, scramble the eggs in the gap, then stir together / Add the rice and soy sauce and stir-fry until hot. Finish with sesame oil and green onions", "Dinner, Lunch, Main dish")
M("Tofu and Broccoli Fried Rice", "Chinese", 10, 12, 3, "500 g|cooked rice, cold; 300 g|firm tofu, crumbled; 200 g|broccoli, finely chopped; 2 cloves|garlic, chopped; 3 tbsp|tamari; 2 tbsp|vegetable oil; 2|green onions, sliced",
  "Fry the tofu in the oil for 5 minutes until golden / Add the garlic and broccoli and stir-fry 3 minutes / Add the rice and tamari and stir-fry until hot / Finish with green onions", "Dinner, Lunch, Main dish")
M("Garlic Chili Oil Noodles", "Chinese", 5, 8, 2, "200 g|wheat noodles; 3 cloves|garlic, minced; 1 tbsp|chili flakes; 1 tsp|sesame seeds; 3 tbsp|vegetable oil; 2 tbsp|soy sauce; 1 tbsp|rice vinegar (or Chinese black vinegar); 1 tsp|sugar; 2|green onions, sliced",
  "Cook the noodles, drain and divide between bowls / Put the garlic, chili flakes, sesame seeds and green onions on top / Heat the oil until shimmering and carefully pour it over to sizzle / Add the soy sauce, vinegar and sugar, toss and serve", "Dinner, Lunch, Main dish")
M("Beef Chow Fun-Style Noodles", "Chinese", 10, 10, 3, "400 g|rice noodles; 300 g|steak, thinly sliced; 1 tbsp|cornstarch; 3 tbsp|soy sauce; 1 tbsp|oyster sauce; 1 tsp|sugar; 200 g|bean sprouts; 4|green onions, in lengths; 2 tbsp|vegetable oil",
  "Soak or cook the noodles as the packet says and drain / Toss the beef with the cornstarch and 1 tbsp soy sauce / Sear the beef in the hot oil for 2 minutes and remove / Stir-fry the noodles with the remaining soy sauce, oyster sauce and sugar until coloured, then add the beef, bean sprouts and green onions for 1 minute", "Dinner, Main dish")
M("Sesame Chicken Ramen Stir-Fry", "Japanese", 10, 10, 2, "2 packs|ramen noodles, seasoning discarded; 250 g|chicken breast, sliced; 1|carrot, cut into matchsticks; 100 g|snow peas; 2 tbsp|soy sauce; 1 tbsp|honey; 1 tbsp|sesame oil; 1 tsp|sesame seeds",
  "Cook the noodles for 2 minutes and drain / Stir-fry the chicken in the sesame oil for 5 minutes / Add the carrot and snow peas for 2 minutes / Add the noodles, soy sauce and honey and toss until glossy. Finish with sesame seeds", "Dinner, Lunch, Main dish")
M("Cumin Lamb Noodles", "Chinese", 10, 12, 3, "300 g|wheat noodles; 400 g|lamb, thinly sliced; 1 tbsp|cumin seeds; 1 tsp|chili flakes; 1|onion, sliced; 2 cloves|garlic, chopped; 2 tbsp|soy sauce; 1 handful|cilantro; 2 tbsp|vegetable oil",
  "Cook the noodles and drain / Sear the lamb in the hot oil for 3 minutes, then add the cumin seeds and chili flakes for 30 seconds / Add the onion and garlic and stir-fry 2 minutes / Toss in the noodles and soy sauce and finish with cilantro", "Dinner, Main dish")
